package com.jarvis.ai;
import android.app.*;
import android.os.*;
import android.content.*;
import android.content.pm.*;
import android.net.*;
import android.provider.Settings;
import android.speech.*;
import android.graphics.Color;
import android.view.*;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import androidx.camera.view.PreviewView;
import java.util.*;

public class MainActivity extends AppCompatActivity{
 TextView chat,status,mode,connection,hud,coreState,offlineState;EditText input;MemoryStore memory;NotificationStore notes;AIClient ai;LanguageManager voice;OfflineEngine offline;OfflineLlmEngine localLlm;ToolRegistry tools;SecureStore secure;CameraXVisionController vision;BrainOrchestrator brain;PerformanceManager performance;boolean cameraOn=false;
 BroadcastReceiver wakeReceiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){listenOnce();}};
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);
  chat=findViewById(R.id.chat);status=findViewById(R.id.status);mode=findViewById(R.id.mode);connection=findViewById(R.id.connection);hud=findViewById(R.id.hud);coreState=findViewById(R.id.coreState);offlineState=findViewById(R.id.offlineState);input=findViewById(R.id.input);
  memory=new MemoryStore(this);notes=new NotificationStore(this);ai=new AIClient();voice=new LanguageManager(this);offline=new OfflineEngine(this);localLlm=new OfflineLlmEngine(this);tools=new ToolRegistry();secure=new SecureStore(this);performance=new PerformanceManager(this);vision=new CameraXVisionController(this,(PreviewView)findViewById(R.id.preview));brain=new BrainOrchestrator(this,offline,localLlm,ai);
  ai.configure(secure.get("endpoint","https://api.openai.com/v1/chat/completions"),secure.get("key",""),secure.get("model","gpt-4o-mini"));
  findViewById(R.id.send).setOnClickListener(v->send());findViewById(R.id.voice).setOnClickListener(v->listenOnce());findViewById(R.id.camera).setOnClickListener(v->toggleCamera());findViewById(R.id.memory).setOnClickListener(v->show("حافظه",memory.recent(60)));findViewById(R.id.notifications).setOnClickListener(v->notificationMenu());findViewById(R.id.wake).setOnClickListener(v->toggleWake());findViewById(R.id.menu).setOnClickListener(this::menu);
  status.setText("● "+(isOnline()?"ONLINE":"OFFLINE"));connection.setText("NET "+(isOnline()?"●":"○")+"  GPU ●  LOCAL ●");mode.setText("AUTO • فارسی • ویس فارسی • نوشته فارسی");hud.setText("◉ CORE READY • VISION STANDBY • MEMORY READY");coreState.setText("◉ JARVIS 2.01 • "+performance.status());offlineState.setText("LOCAL: آماده");
  append("جارویس","سلام. من JARVIS 2.01 هستم. هسته محلی، Vision، Tools و حالت چندمغزه آماده‌اند.");
  localLlm.prepare((ok,msg)->{offlineState.setText(ok?"LOCAL: آماده • GPU":"LOCAL: "+msg);return kotlin.Unit.INSTANCE;});
  if(!"1".equals(secure.get("activated","")))new Handler().postDelayed(this::passwordGate,450);
  registerReceiver(wakeReceiver,new IntentFilter("com.jarvis.ai.WAKE"),Context.RECEIVER_NOT_EXPORTED);
  if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},77);
  updateConnectionLoop();
 }
 void updateConnectionLoop(){status.setText("● "+(isOnline()?"ONLINE":"OFFLINE"));connection.setText("NET "+(isOnline()?"●":"○")+"  GPU ●  LOCAL ●");coreState.setText("◉ JARVIS 2.01 • "+performance.status());new Handler().postDelayed(this::updateConnectionLoop,5000);}
 boolean isOnline(){return ((ConnectivityManager)getSystemService(CONNECTIVITY_SERVICE)).getActiveNetwork()!=null;}
 void send(){String q=input.getText().toString().trim();if(q.isEmpty())return;input.setText("");SafetyEngine.Result safe=SafetyEngine.check(q);if(safe.verdict==SafetyEngine.Verdict.BLOCK){append("جارویس",safe.message);return;}append("شما",q);memory.add("user",q);
  String l=q.toLowerCase(Locale.ROOT);
  if(l.startsWith("باز کن ")||l.startsWith("open ")||l.startsWith("اجرا ")){String a=q.replaceFirst("(?i)^(باز کن|open|اجرا)\s*","");respond(tools.execute(this,"open "+a));return;}
  if(l.contains("پاسخ پیام")||l.contains("به پیام")||l.contains("reply message")){confirmReply();return;}
  offlineState.setText("THINKING • "+brain.mode());
  brain.ask(q,memory.recent(24),s->{offlineState.setText("LOCAL: آماده");respond(s);});
 }
 void respond(String s){String safe=SafetyEngine.output(s);append("جارویس",safe);memory.add("assistant",safe);voice.speak(safe,.95f);}
 void listenOnce(){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},8);return;}Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"fa-IR");i.putExtra(RecognizerIntent.EXTRA_PARTIAL_RESULTS,true);startActivityForResult(i,99);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==99&&c==RESULT_OK&&d!=null){ArrayList<String>x=d.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(x!=null&&!x.isEmpty()){input.setText(x.get(0));send();}}}
 void toggleCamera(){if(checkSelfPermission(android.Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.CAMERA},42);return;}cameraOn=!cameraOn;findViewById(R.id.preview).setVisibility(cameraOn?View.VISIBLE:View.GONE);findViewById(R.id.cameraDim).setVisibility(cameraOn?View.VISIBLE:View.GONE);if(cameraOn){vision.startLive(ai,s->{hud.setText("◉ LIVE VISION • "+s);},performance.visionIntervalMs());((Button)findViewById(R.id.camera)).setText("👁 LIVE VISION • ON");hud.setText("◉ LIVE VISION • CAMERA ACTIVE");}else{vision.stop();((Button)findViewById(R.id.camera)).setText("👁 Live Camera");hud.setText("◉ CORE READY • VISION STANDBY");}}
 void toggleWake(){if(checkSelfPermission(android.Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},8);return;}try{startForegroundService(new Intent(this,JarvisVoiceService.class));status.setText("● BACKGROUND VOICE");respond("حالت پس‌زمینه و Hey JARVIS فعال شد.");}catch(Exception e){respond("فعال‌سازی ویس پس‌زمینه ناموفق بود.");}}
 void menu(View v){PopupMenu p=new PopupMenu(this,v);String[] opts={"🤖 Brain Mode","⚡ Performance","🌐 زبان اصلی: فارسی","🎙 زبان ویس: فارسی","⌨ زبان نوشته: فارسی","👁 Live Vision","🧩 Tools","💾 Memory","🔔 Notifications","📱 App Control","🔐 Security","🛡 Safety Filter","📊 Activity / Status","⚙ AI Settings","🛡 Android Permissions","ℹ About JARVIS 2.01"};for(String x:opts)p.getMenu().add(x);p.setOnMenuItemClickListener(i->{String s=i.getTitle().toString();if(s.contains("Brain"))brainMenu();else if(s.contains("Performance"))performanceMenu();else if(s.contains("Live Vision")){if(!cameraOn)toggleCamera();}else if(s.contains("AI Settings"))setupAI();else if(s.contains("Permissions"))permissionMenu();else if(s.contains("Notifications"))notificationMenu();else if(s.contains("Security"))show("Security","Activation password is protected in Android encrypted storage.");else if(s.contains("Safety"))show("Safety","Simple profanity is allowed. Explicit +18 and actionable harm instructions are blocked.");else if(s.contains("Activity"))show("JARVIS Status",performance.status()+"\n\nNetwork: "+(isOnline()?"ONLINE":"OFFLINE")+"\nBrain: "+brain.mode()+"\nVision: "+(cameraOn?"LIVE":"STANDBY")+"\nBackground Voice: "+("1".equals(secure.get("wake",""))));else if(s.contains("Tools"))show("Tools","Open apps • Notifications • Reply with confirmation • Camera • Browser • Calculator • Android controls.");else if(s.contains("App Control"))show("App Control","نمونه: «باز کن Chrome»، «باز کن YouTube»، «باز کن تلگرام».");else if(s.contains("Memory"))show("Memory",memory.recent(60));else if(s.contains("زبان"))show("Language","فارسی زبان اصلی JARVIS است؛ Voice و Text language نیز فارسی تنظیم شده‌اند.");else show("JARVIS 2.01","Iron-Man HUD • Multi-Brain • GPU • Live Vision • Voice • Memory • Tools • Safety");return true;});p.show();}
 void brainMenu(){String[] x={"AUTO • پیشنهاد JARVIS","LOCAL • آفلاین","CLOUD • آنلاین","GPT • OpenAI"};int n=brain.mode().ordinal();new AlertDialog.Builder(this).setTitle("🧠 Brain Mode").setSingleChoiceItems(x,n,(d,w)->{brain.setMode(BrainOrchestrator.Brain.values()[w]);mode.setText(x[w]+" • فارسی");d.dismiss();respond("حالت مغز روی "+x[w]+" قرار گرفت.");}).show();}
 void performanceMenu(){String[] x={"Battery Saver","Balanced","Performance","Maximum AI / Turbo"};int n=performance.mode().ordinal();new AlertDialog.Builder(this).setTitle("⚡ Performance").setSingleChoiceItems(x,n,(d,w)->{performance.setMode(PerformanceManager.Mode.values()[w]);coreState.setText("◉ JARVIS 2.01 • "+performance.status());d.dismiss();respond("حالت عملکرد تغییر کرد.");}).show();}
 void permissionMenu(){new AlertDialog.Builder(this).setTitle("Android Permissions").setItems(new String[]{"🎙 Microphone","👁 Camera","💬 Notification Access","📱 Accessibility"},(d,w)->{if(w==0)requestPermissions(new String[]{android.Manifest.permission.RECORD_AUDIO},8);else if(w==1)requestPermissions(new String[]{android.Manifest.permission.CAMERA},42);else if(w==2)startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"));else startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}).show();}
 void notificationMenu(){new AlertDialog.Builder(this).setTitle("💬 Incoming Messages").setMessage(notes.briefing()).setPositiveButton("Reply with my approval",(d,w)->confirmReply()).setNeutralButton("Notification Access",(d,w)->startActivity(new Intent("android.settings.ACTION_NOTIFICATION_LISTENER_SETTINGS"))).setNegativeButton("Close",null).show();}
 void confirmReply(){EditText e=new EditText(this);e.setHint("متن پاسخ");e.setText("سلام، پیام شما را دیدم.");new AlertDialog.Builder(this).setTitle("تأیید ارسال").setMessage(notes.briefing()).setView(e).setPositiveButton("ارسال",(d,w)->{String s=NotificationAction.replyLatest(this,SafetyEngine.output(e.getText().toString()));respond(s.equals("انجام شد.")?"پاسخ تأییدشده ارسال شد.":s);}).setNegativeButton("لغو",null).show();}
 void setupAI(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);EditText e=new EditText(this);e.setHint("Endpoint");e.setText(secure.get("endpoint","https://api.openai.com/v1/chat/completions"));EditText k=new EditText(this);k.setHint("API Key");k.setInputType(129);EditText m=new EditText(this);m.setHint("Model");m.setText(secure.get("model","gpt-4o-mini"));l.addView(e);l.addView(k);l.addView(m);new AlertDialog.Builder(this).setTitle("GPT / Cloud").setMessage("API key در فضای رمزنگاری‌شده Android ذخیره می‌شود.").setView(l).setPositiveButton("ذخیره",(d,w)->{secure.put("endpoint",e.getText().toString());secure.put("key",k.getText().toString());secure.put("model",m.getText().toString());ai.configure(e.getText().toString(),k.getText().toString(),m.getText().toString());respond("اتصال AI ذخیره شد.");}).setNegativeButton("لغو",null).show();}
 void passwordGate(){EditText e=new EditText(this);e.setInputType(129);e.setHint("رمز JARVIS");new AlertDialog.Builder(this).setTitle("فعال‌سازی JARVIS").setMessage("رمز فعال‌سازی را وارد کن.").setView(e).setCancelable(false).setPositiveButton("فعال‌سازی",(d,w)->{if("ayhan2012".equals(e.getText().toString())){secure.put("activated","1");respond("فعال‌سازی موفق بود.");}else{Toast.makeText(this,"رمز نادرست است.",Toast.LENGTH_LONG).show();new Handler().postDelayed(this::passwordGate,300);}}).show();}
 void append(String a,String b){chat.append("\n"+a+"  ›  "+b+"\n");}
 void show(String a,String b){new AlertDialog.Builder(this).setTitle(a).setMessage(b).setPositiveButton("باشه",null).show();}
 @Override protected void onDestroy(){vision.stop();localLlm.release();try{unregisterReceiver(wakeReceiver);}catch(Exception e){}super.onDestroy();}
}